            out.append(b"$%d\r\n%s\r\n" % (len(b), b))
        self.sock.sendall(b"".join(out))
        return self._read()


def score(raw):
    """Render a zset score as a JSON number, preferring int when exact."""
    f = float(raw)
    return int(f) if f.is_integer() and abs(f) < 2**53 else f


def main():
    r = Resp()

    db = 0
    for line in r.cmd("INFO", "keyspace").splitlines():
        if line.startswith("db"):
            db = int(line.split(":", 1)[0][2:])
            break

